using System;
using System.Collections.Generic;
using System.Net.Http;
using System.Net.Http.Json;
using System.Threading;
using System.Threading.Tasks;

namespace enki.Services;

/// <summary>Thin wrapper over Supabase's autogenerated REST API (Postgrest) — the same
/// <c>/rest/v1/{table}</c> endpoints documented in docs/supabase-sync/07-guia-app-externa.md. Every call
/// refreshes the access token first via <see cref="PolarAuthService.EnsureFreshTokenAsync"/>, so callers
/// never think about token expiry.</summary>
// CA1001: _http (HttpClient) is disposable, but this service is an app-lifetime singleton — same rationale
// as PolarSyncService/PolarAuthService (Fase 10, docs/analisis-proyecto/roadmap.md).
#pragma warning disable CA1001
public sealed class SupabaseRestClient
#pragma warning restore CA1001
{
    private const int PageSize = 500;

    /// <summary>Bounds every request so a stalled connection fails fast into
    /// <see cref="PolarSyncService"/>'s existing offline handling instead of hanging for the default
    /// 100 s <see cref="HttpClient"/> timeout.</summary>
    private static readonly TimeSpan RequestTimeout = TimeSpan.FromSeconds(20);

    private readonly PolarAuthService _auth;
    private readonly HttpClient _http;
    private readonly string? _anonKey;

    /// <summary>Production callers omit every optional parameter and get the real Supabase project
    /// configured via <see cref="SupabaseConfig"/>. Tests pass <paramref name="httpHandler"/> (a fake
    /// transport) together with a fake <paramref name="baseUrl"/>/<paramref name="anonKey"/> so the whole
    /// push/pull contract can be exercised without a live network dependency or a real
    /// <c>local.properties</c> — see <c>SupabaseRestClientTests</c>.</summary>
    public SupabaseRestClient(PolarAuthService auth, HttpMessageHandler? httpHandler = null, string? baseUrl = null, string? anonKey = null)
    {
        _auth = auth;
        baseUrl ??= SupabaseConfig.Url;
        _anonKey = anonKey ?? SupabaseConfig.AnonKey;
        _http = new HttpClient(httpHandler ?? new HttpClientHandler())
        {
            BaseAddress = !string.IsNullOrWhiteSpace(baseUrl) ? new Uri(baseUrl.TrimEnd('/') + "/") : null,
            Timeout = RequestTimeout
        };
    }

    /// <summary>Upserts <paramref name="rows"/> into <paramref name="table"/> keyed by <c>id</c> — the
    /// push half of docs/supabase-sync/04's sync algorithm. Returns the server's authoritative version of
    /// each row (post-LWW-trigger) so the caller can tell who won each conflict.</summary>
    public async Task<List<T>> UpsertAsync<T>(string table, List<T> rows, CancellationToken ct)
    {
        if (rows.Count == 0) return [];

        await PrepareRequestHeadersAsync(ct);

        using var request = new HttpRequestMessage(HttpMethod.Post, $"rest/v1/{table}?on_conflict=id");
        AddAuthHeaders(request);
        request.Headers.Add("Prefer", "resolution=merge-duplicates,return=representation");
        request.Content = JsonContent.Create(rows);

        using var response = await _http.SendAsync(request, ct);
        response.EnsureSuccessStatusCode();

        var body = await response.Content.ReadFromJsonAsync<List<T>>(cancellationToken: ct);
        return body ?? [];
    }

    /// <summary>Pulls every row of <paramref name="table"/> with <c>updated_at &gt; updatedAfterMs</c>,
    /// oldest first, paging until a page comes back smaller than <see cref="PageSize"/>. Ordered by
    /// <c>(updated_at, id)</c> and, from the second page on, filtered by that same compound cursor instead
    /// of a bare <c>updated_at.gt</c> — a bulk push can trigger-stamp more than <see cref="PageSize"/> rows
    /// with the exact same millisecond, and a bare timestamp cursor would silently drop whichever of those
    /// tied rows didn't fit on the page where the tie was cut, since the next page's <c>gt</c> filter
    /// excludes the tie value entirely.</summary>
    public async Task<List<T>> SelectUpdatedSinceAsync<T>(string table, long updatedAfterMs, CancellationToken ct)
    {
        var results = new List<T>();
        var cursorUpdatedAt = updatedAfterMs;
        string? cursorId = null;

        while (true)
        {
            await PrepareRequestHeadersAsync(ct);

            var filter = cursorId is null
                ? $"updated_at=gt.{cursorUpdatedAt}"
                : $"or=(updated_at.gt.{cursorUpdatedAt},and(updated_at.eq.{cursorUpdatedAt},id.gt.{Uri.EscapeDataString(cursorId)}))";

            using var request = new HttpRequestMessage(
                HttpMethod.Get,
                $"rest/v1/{table}?{filter}&order=updated_at.asc,id.asc&limit={PageSize}");
            AddAuthHeaders(request);

            using var response = await _http.SendAsync(request, ct);
            response.EnsureSuccessStatusCode();

            var page = await response.Content.ReadFromJsonAsync<List<T>>(cancellationToken: ct) ?? [];
            results.AddRange(page);

            if (page.Count < PageSize) break;

            var last = page[^1];
            cursorUpdatedAt = ExtractUpdatedAt(last);
            cursorId = ExtractId(last);
        }

        return results;
    }

    private async Task PrepareRequestHeadersAsync(CancellationToken ct) => await _auth.EnsureFreshTokenAsync(ct);

    private void AddAuthHeaders(HttpRequestMessage request)
    {
        request.Headers.Add("apikey", _anonKey);
        request.Headers.Add("Authorization", $"Bearer {_auth.AccessToken}");
    }

    /// <summary>Reflection-free access to the wire DTOs' shared <c>UpdatedAt</c>/<c>Id</c> fields, used only
    /// to advance the compound pagination cursor within a single page loop — every wire DTO in this app
    /// implements <see cref="IPolarWireRow"/> precisely so this cast is safe.</summary>
    private static long ExtractUpdatedAt<T>(T row) => ((IPolarWireRow)row!).UpdatedAt;
    private static string ExtractId<T>(T row) => ((IPolarWireRow)row!).Id;
}

/// <summary>Implemented by every Postgrest wire DTO in <c>services/polar/PolarWireDtos.cs</c> so
/// <see cref="SupabaseRestClient"/> can page results without knowing the concrete DTO type.</summary>
public interface IPolarWireRow
{
    string Id { get; }
    long UpdatedAt { get; }
}
